(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [120+Math.sin(t*0.4)*110, 70+Math.cos(t*0.35)*50, 0.07, 2.2, 0.0],
    [360+Math.cos(t*0.45)*100, 80+Math.sin(t*0.5)*60, 0.09, 1.8, 1.0],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*100, 0.055, 2.5, 2.0],
    [80+Math.cos(t*0.65+1)*90, 180+Math.sin(t*0.5+3)*70, 0.11, 1.6, 3.0],
    [400+Math.sin(t*0.38+4)*100, 170+Math.cos(t*0.75+2)*80, 0.065, 2.8, 4.0],
    [200+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*90, 0.08, 2.0, 5.0],
    [300+Math.sin(t*0.55+3)*80, 40+Math.cos(t*0.6+4)*50, 0.1, 1.9, 0.5],
    [160+Math.cos(t*0.25+1.5)*100, 140+Math.sin(t*0.4+2.5)*80, 0.075, 2.3, 1.5]
  ];
  let aS=0, iS=0, harm=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1=Math.sin(d*f-t*sp+ph);
    const w2=Math.sin(d*f*1.618-t*sp*0.618+ph*2);
    const w3=Math.cos(d*f*0.5+t*sp*0.4+ph*0.7);
    aS+=w1*0.5+w2*0.3+w3*0.2;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5)*0.6+Math.cos(d*f*1.3-t*sp*0.3+ph)*0.4;
    harm+=Math.sin(d*f*0.85-t*sp*1.2+ph*0.5)*0.5;
  }
  const act=aS/8, inh=iS/8, hr=harm/8;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.9)+Math.sin(sx*0.028-sy*0.038+t*1.2)+Math.sin(sx*0.02+sy*0.045-t*0.7))/3;
  const micro=Math.sin(sx*0.12+t*1.5)*Math.sin(sy*0.11-t*1.3)*0.15+Math.sin((sx-sy)*0.08+t*2)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.8)+Math.sin(dist*0.035+ang*5-t*1.3)+Math.sin(dist*0.06-ang*2+t*2.2))*0.3;
  const moire=Math.sin(dist*0.12)*Math.sin(ang*6+t*0.8)*0.2;
  const voroX=Math.sin(sx*0.08+t*0.2)*20, voroY=Math.cos(sy*0.08-t*0.15)*20;
  const cellEdge=1-Math.pow(Math.max(0,1-Math.abs(Math.sin((sx+voroX)*0.15)*Math.sin((sy+voroY)*0.15))*2),3);
  const feed=act*0.45-inh*0.3+bg*0.15+spiral*0.12+hr*0.1+micro+moire;
  const r1=Math.tanh(feed*2.5);
  const r2=Math.tanh(feed*1.8+r1*0.6);
  const reaction=r1*0.6+r2*0.4;
  const edge=Math.abs(reaction)>0.65?1+Math.abs(reaction)*0.25:1.0;
  const glow=Math.pow(Math.max(0,Math.abs(reaction)),2)*0.3;
  const v=Math.tanh(reaction*1.2)*0.5+0.5+glow*0.15;
  const pal=[[5,12,52],[12,45,95],[18,85,125],[25,135,135],[60,170,130],[150,195,100],[210,190,70],[225,145,55],[200,95,55],[155,50,65],[95,25,65],[45,15,55],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const smooth=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+glow*0.3;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*smooth)*lum*edge+cellEdge*8)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*smooth)*lum*edge+cellEdge*5)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*smooth)*lum*edge+cellEdge*12)|0)
  ];
}
